import{z as i,x as A,o as n,c as d,q as t,j as B,D as E,d as r,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"连接顺序搜索空间","description":"","frontmatter":{"title":"连接顺序搜索空间","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/join-order-space.md","filePath":"cs/join-order-space.md","lastUpdated":1791063341000}'),p={name:"cs/join-order-space.md"};function D(C,a,u,h,c,m){const s=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=t('<h1 id="连接顺序搜索空间" tabindex="-1">连接顺序搜索空间 <a class="header-anchor" href="#连接顺序搜索空间" aria-label="Permalink to &quot;连接顺序搜索空间&quot;">​</a></h1><div class="epigraph"><p>左深树是链，bushy 树允许两侧都是连接结果；再限制「只连接有谓词的分量」，空间从阶乘降到连通子图。</p><footer>—— 据 Vance and Maier；Moerkotte and Neumann, DPCCP；Selinger 左深限制对照</footer></div><p><a href="/cs/selinger-dp">上一课</a>在左深子集 DP 上钉了有趣序。本课不重写支配剪枝。缺口是树形本身：左深、右深、bushy，以及是否允许无连接谓词的笛卡尔积中间结果。空间大小决定 \\(n{=}12\\) 还能不能精确 DP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>左深：每个连接的一侧是基表。哈希连接时 build 侧若总是「到目前为止的结果」，内存形状固定，流水线友好。bushy：两边都可以是子连接树，有时避免巨大中间结果（两对小连接先做完再连）。右深用于某些并行流水。缺口是<strong>枚举哪些二叉树</strong>，不是再定义 ⋈。</p><p>笛卡尔积：查询图不连通时必须做积。连通查询上，若仍枚举断开子集，会多出极贵的积。DPccp 只枚举连通互补对，空间随查询图稀疏度降。星型查询与链状查询的图完全不同。</p><p><span class="marginnote">数字实例：\\(n{=}12\\) 张表，左深排列有 \\(12! \\approx 4.8\\) 亿种；就算优化器每秒能评估一百万棵树，也要算八分多钟。这就是为什么表一多，精确 DP 必须让位给 GOO、IKKBZ 这类启发式。</span></p><p><span class="marginnote">直觉类比：bushy 像淘汰赛——参赛表两两先打「小组赛」（小连接），胜者再捉对决赛；左深则是联赛制，一个队（中间结果）从头踢到尾，每轮都背着全部累计包袱上场。</span></p><p><span class="marginnote">Moerkotte and Neumann 的 DPCCP 在连通补对上 DP。Vance and Maier 讨论 bushy 枚举。启发式（GOO、IKKBZ）在 \\(n\\) 太大时替换精确 DP，本课点名不把启发式当最优。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查询图：顶点关系，边是连接谓词。合法连接：两连通分量之间有边（或显式允许积）。左深 DP：状态仍是子集，扩展点必须与 \\(S\\) 有边。bushy DP：状态是子集，转移是拆成两个非空互补连通子集。</p><p>超时与截止：精确搜不完就返回当前最佳（任意时间算法）。这与自适应处理不同：这里还在优化时，尚未执行。</p>',12)),(n(),B(l,null,{default:E(()=>[o(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20QG%5B%22%E6%9F%A5%E8%AF%A2%E5%9B%BE%22%5D%20--%3E%20LD%5B%22%E5%B7%A6%E6%B7%B1%E9%93%BE%22%5D%0A%20%20QG%20--%3E%20BU%5B%22bushy%20%E4%BA%8C%E5%8F%89%E6%A0%91%22%5D%0A%20%20QG%20--%3E%20CC%5B%22%E5%8F%AA%E8%BF%9E%E9%80%9A%E4%BA%92%E8%A1%A5%E5%AF%B9%22%5D%0A%20%20LD%20--%3E%20N1%5B%22n!%20%E9%87%8F%E7%BA%A7%E6%8E%92%E5%88%97%22%5D%0A%20%20BU%20--%3E%20N2%5B%22Catalan%20%C3%97%20%E5%8F%B6%E6%A0%87%22%5D%0A%20%20CC%20--%3E%20N3%5B%22%E9%9A%8F%E7%A8%80%E7%96%8F%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"外连接有顺序限制：不能随便交换左右，bushy 形状更受限。半连接可当缩减器插在真连接前（分布式后课）。代价模型必须给笛卡尔积很高的估计，否则 DP 会「先积再滤」——谓词下推本应先避免积，逻辑改写与物理搜索要配合。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为连接顺序只影响快慢、选错了顶多慢一点。实际上若允许断开子集，优化器可能选中「先做笛卡尔积再过滤」的计划——两张百万行的表先硬乘，中间结果是万亿行，内存和磁盘都扛不住。")],-1)),(n(),B(l,null,{default:E(()=>[o(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22S%20%3D%20%7BR1%2C%20R2%2C%20R3%2C%20R4%7D%22%5D%20--%3E%20P1%5B%22%E6%8B%86%E6%88%90%20%7BR1%2C%20R2%7D%20%E4%B8%8E%20%7BR3%2C%20R4%7D%22%5D%0A%20%20S%20--%3E%20P2%5B%22%E6%8B%86%E6%88%90%20%7BR1%7D%20%E4%B8%8E%20%7BR2%2C%20R3%2C%20R4%7D%22%5D%0A%20%20P1%20--%3E%20C1%5B%22%E4%B8%A4%E5%8D%8A%E4%B9%8B%E9%97%B4%E6%9C%89%E8%BF%9E%E6%8E%A5%E8%BE%B9%EF%BC%9F%22%5D%0A%20%20C1%20--%3E%7C%22%E6%9C%89%22%7C%20OK%5B%22%E5%90%88%E6%B3%95%20bushy%20%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20C1%20--%3E%7C%22%E6%97%A0%22%7C%20BAD%5B%22%E6%96%AD%E5%BC%80%E5%AD%90%E9%9B%86%EF%BC%9A%E7%AC%9B%E5%8D%A1%E5%B0%94%E7%A7%AF%EF%BC%8C%E5%89%AA%E6%8E%89%22%5D%0A%20%20P2%20--%3E%20C2%5B%22%E5%90%8C%E6%A0%B7%E6%A3%80%E6%9F%A5%E4%BA%92%E8%A1%A5%E4%B8%94%E8%BF%9E%E9%80%9A%22%5D%0A%20%20C2%20--%3E%20OK2%5B%22%E5%90%88%E6%B3%95%EF%BC%88%E5%B7%A6%E6%B7%B1%E5%BC%8F%E6%89%A9%E5%B1%95%EF%BC%89%22%5D%0A%20%20OK%20--%3E%20F%5B%22%E8%BF%9B%E5%85%A5%20DP%20%E7%8A%B6%E6%80%81%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20OK2%20--%3E%20F%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>并行与交换算子后课才加；本课空间仍是逻辑连接树加物理算法标签。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不量化基数误差如何沿 bushy 树爆炸——下一课。也不把遗传算法、模拟退火写进主干必做，只承认 \\(n\\) 很大时近似搜索存在。</p><p>后课默认：谈到连接顺序，先画查询图，再选左深或 bushy、是否强制连通。星型多表不是「随便 nested loop」。</p><p>搜索空间是优化器的复杂度来源；有趣序是每个节点上的标签，不是另一套空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>左深、bushy、连通限制决定能否精确 DP。</li><li>断开子集等于中间笛卡尔积，通常应禁止。</li><li>基数估计误差传播下一课：空间搜对了，数字错仍选错树。</li><li>出处：Selinger；Vance and Maier；Moerkotte and Neumann。</li></ul>',7))])}const F=i(p,[["render",D]]);export{b as __pageData,F as default};
